 void Plot(Rect r,FinchDefinition a,FinchDefinition b){float max=0;foreach(float n in a.torque)max=Mathf.Max(max,n);foreach(float n in b.torque)max=Mathf.Max(max,n);max=Mathf.Ceil(max/20)*20;Label(new Rect(r.xMax-90,r.y-18,90,18),max.ToString("F0")+" Nm",13,muted);for(int grid=0;grid<3;grid++){float y=r.y+r.height*grid/2;Fill(new Rect(r.x,y,r.width,1),new Color(.16f,.22f,.26f));}Curve(r,a,max,new Color(.45f,.54f,.59f));Curve(r,b,max,accent);Label(new Rect(r.x,r.yMax+1,120,20),"900 RPM",12,muted);Label(new Rect(r.xMax-100,r.yMax+1,100,20),"6500 RPM",12,muted);}
 void Curve(Rect r,FinchDefinition d,float max,Color color){var matrix=GUI.matrix;var old=GUI.color;GUI.color=color;for(int i=1;i<d.rpm.Length;i++){var a=new Vector2(r.x+(d.rpm[i-1]-900)/5600*r.width,r.yMax-d.torque[i-1]/max*r.height);var b=new Vector2(r.x+(d.rpm[i]-900)/5600*r.width,r.yMax-d.torque[i]/max*r.height);GUI.matrix=matrix*Matrix4x4.TRS(new Vector3(a.x,a.y,0),Quaternion.Euler(0,0,Mathf.Atan2(b.y-a.y,b.x-a.x)*Mathf.Rad2Deg),Vector3.one);GUI.DrawTexture(new Rect(0,0,Vector2.Distance(a,b),2),Texture2D.whiteTexture);GUI.matrix=matrix;}GUI.color=old;}
